record.field:
for rec in records:
    # 1. Validar vinculación obligatoria de Proyecto y Frente/Contrato
    if not rec.x_proyecto_id:
        raise UserError("Es obligatorio seleccionar el 'Proyecto Global' para registrar la requisición.")

    if not rec.x_frente_id:
        raise UserError("Es obligatorio asignar el 'Bloque / Frente / Contrato' de destino.")

    # 2. Validar motivo obligatorio para insumos extraordinarios
    if rec.x_tipo_requerimiento == 'extraordinario':
        if not rec.x_motivo_extraordinario or len(rec.x_motivo_extraordinario.strip()) < 15:
            raise UserError(
                "Para requerimientos extraordinarios, es obligatorio proporcionar una justificación detallada "
                "en el campo 'Motivo Extraordinario' (mínimo 15 caracteres)."
            )

for order in records:
    # Identificar si el usuario actual pertenece al perfil de Control de Costos o Administrador
    is_cost_manager = env.user.has_group('project.group_project_manager') or env.user.has_group('base.group_system')

    for line in order.order_line:
        # Obtener el precio tope autorizado del insumo en la cuenta analítica o catálogo base
        precio_limite = line.product_id.x_precio_limite_frente or line.product_id.standard_price

        if line.price_unit > precio_limite and not is_cost_manager:
            raise UserError(
                f"El precio unitario del insumo '{line.product_id.display_name}' (${line.price_unit:,.2f}) "
                f"supera el precio tope autorizado (${precio_limite:,.2f}) para este frente.\n\n"
                f"Esta orden requiere la revisión y autorización expresa del área de Control de Costos."
            )

for rec in records:
    if rec.x_tipo_requerimiento == 'extraordinario':
        # Verificar si existen archivos adjuntos en el registro
        adjuntos = env['ir.attachment'].search([
            ('res_model', '=', rec._name),
            ('res_id', '=', rec.id)
        ])

        # Exigir vínculo con Orden de Cambio o al menos un documento adjunto
        if not rec.x_orden_cambio_id and not adjuntos:
            raise UserError(
                f"No se puede autorizar la requisición extraordinaria '{rec.name}'.\n\n"
                f"Es obligatorio vincular un folio de Orden de Cambio o adjuntar el Dictamen Técnico firmado."
            )

for move in records:
    for line in move.invoice_line_ids:
        po_line = line.purchase_line_id
        if po_line:
            # 1. Validar que la cantidad facturada no supere lo recibido físicamente en obra
            if line.quantity > po_line.qty_received:
                raise UserError(
                    f"Discrepancia en 3-Way Matching para el insumo '{line.product_id.display_name}':\n"
                    f"La cantidad a facturar ({line.quantity} {line.product_uom_id.name}) supera la cantidad "
                    f"recibida en almacén de obra ({po_line.qty_received} {po_line.product_uom.name})."
                )

            # 2. Validar que el precio unitario facturado no exceda el precio negociado en la OC
            if line.price_unit > po_line.price_unit:
                raise UserError(
                    f"Discrepancia de precio para el insumo '{line.product_id.display_name}':\n"
                    f"El precio unitario facturado (${line.price_unit:,.2f}) es mayor al precio negociado "
                    f"en la Orden de Compra (${po_line.price_unit:,.2f})."
                )

UMBRAL_FINANCIERO = 100000.0  # $100,000.00 MXN

for order in records:
    if order.amount_total >= UMBRAL_FINANCIERO:
        # Publicar notificación automática en el Chatter del documento
        order.message_post(
            body=f"⚠  **Alerta de Compra Mayorista**: Esta orden supera el umbral de "
                 f"${UMBRAL_FINANCIERO:,.2f} MXN (Monto Total: ${order.amount_total:,.2f} MXN). "
                 f"Requiere la firma/aprobación de Dirección Ejecutiva.",
            subtype_xmlid="mail.mt_note"
        )

        # Bloquear confirmación si no cuenta con la casilla de validación ejecutiva
        if not order.x_aprobado_direccion and not env.user.has_group('base.group_system'):
            raise UserError(
                f"La Orden de Compra '{order.name}' por un monto de ${order.amount_total:,.2f} MXN "
                f"requiere la aprobación formal del perfil Dirección antes de emitirse al proveedor."
            )
